def _create_audit_checkpoint(self) -> None:
    idempotency_key = self._audit_idempotency_key()
    if idempotency_key is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 审计创建拒绝查询参数：参数校验先于体校验与认证结构。
    if parse_qsl(urlsplit(self.path).query, keep_blank_values=True):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 正文必须恰为空对象（重复键等非法 JSON 同样拒绝）。
    raw_body = self._read_raw_body()
    parsed = None if raw_body is None else self._read_json_object(raw_body)
    if parsed is None or parsed:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 仅接受单一 SLA-Auth：代理头、缺失、重复或结构非法均为非法请求。
    if self.headers.get_all(SLA_DELEGATION_HEADER):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    auth = self._parse_sla_auth()
    if auth is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    body_digest = hashlib.sha256(raw_body).hexdigest()
    status, payload = self._apply_audit_checkpoint(auth, body_digest, idempotency_key)
    self._json(status, payload)

@staticmethod
def _audit_difference(
    account_id: str,
    difference_type: str,
    entry_seq: int | None,
    reference_seq: int | None,
    expected: Any = None,
    actual: Any = None,
) -> dict[str, Any]:
    return {
        "accountId": account_id,
        "type": difference_type,
        "entrySeq": entry_seq,
        "referenceSeq": reference_seq,
        "expected": expected,
        "actual": actual,
    }

@staticmethod
def _audit_pair_delta(pair: list[dict[str, Any]]) -> int:
    return sum(entry["delta_micros"] for entry in pair)

def _build_audit_document(
    self, database: Any, entry_seq_bound: int
) -> dict[str, Any]:
    # 在写事务内冻结账本上界、账户余额、争议冻结额、升级托管额与仲裁结果。
    differences: list[dict[str, Any]] = []

    deposits = {
        row["deposit_seq"]: row
        for row in database.execute(
            "SELECT deposit_seq, machine_id, amount_micros FROM fund_deposits"
        ).fetchall()
    }
    settlements = {
        row["settlement_seq"]: row
        for row in database.execute(
            "SELECT settlement_seq, sla_id, evaluation_seq, result,"
            " amount_micros, payer_id, payee_id FROM settlements"
        ).fetchall()
    }
    evaluations = {
        row["evaluation_seq"]: row
        for row in database.execute(
            "SELECT evaluation_seq, sla_id FROM sla_evaluation_idempotency_records"
        ).fetchall()
    }
    sla_ids = {row["id"] for row in database.execute("SELECT id FROM slas")}
    disputes_by_id: dict[str, Any] = {}
    for row in database.execute(
        "SELECT id, settlement_seq, claimant_id, payer_id, payee_id,"
        " amount_micros, state FROM disputes"
    ).fetchall():
        disputes_by_id[row["id"]] = row
    escalations = {
        row["escalation_seq"]: row
        for row in database.execute(
            "SELECT escalation_seq, dispute_id, amount_micros"
            " FROM dispute_escalations"
        ).fetchall()
    }
    arbitrations = {
        row["arbitration_seq"]: row
        for row in database.execute(
            "SELECT arbitration_seq, escalation_seq, dispute_id,"
            " arbitrator_id, decision, amount_micros FROM dispute_arbitrations"
        ).fetchall()
    }

    entries = [
        dict(row)
        for row in database.execute(
            "SELECT entry_seq, kind, reference_seq, account_id, delta_micros,"
            " balance_after_micros FROM ledger_entries"
            " WHERE entry_seq <= ? ORDER BY entry_seq ASC",
            (entry_seq_bound,),
        ).fetchall()
    ]
    stored_balances = {
        row["account_id"]: row["balance_micros"]
        for row in database.execute(
            "SELECT account_id, balance_micros FROM ledger_accounts"
        ).fetchall()
    }

    # 每个 open 争议按收款账户计入冻结。
    frozen_by_account: dict[str, int] = {}
    for dispute in disputes_by_id.values():
        if dispute["state"] == "open":
            frozen_by_account[dispute["payee_id"]] = (
                frozen_by_account.get(dispute["payee_id"], 0)
                + dispute["amount_micros"]
            )

    account_ids = set(stored_balances) | {
        entry["account_id"] for entry in entries
    }
    # 外部清算账户即使尚无任何分录也参与核对（余额取零）。
    account_ids.add(CLEARING_ACCOUNT_ID)
    entries_by_account: dict[str, list[dict[str, Any]]] = {
        account_id: [] for account_id in account_ids
    }
    for entry in entries:
        entries_by_account.setdefault(entry["account_id"], []).append(entry)

    # 逐账户重放上界内分录：累计值、每步余额，并与存储余额核对。
    accounts: list[dict[str, Any]] = []
    for account_id in sorted(account_ids):
        account_entries = entries_by_account.get(account_id, [])
        running = 0
        for entry in account_entries:
            expected_balance = running + entry["delta_micros"]
            if entry["balance_after_micros"] != expected_balance:
                differences.append(
                    self._audit_difference(
                        account_id,
                        "step_balance_mismatch",
                        entry["entry_seq"],
                        entry["reference_seq"],
                        expected_balance,
                        entry["balance_after_micros"],
                    )
                )
            running = expected_balance
        stored = stored_balances.get(account_id, 0)
        if running != stored:
            differences.append(
                self._audit_difference(
                    account_id, "balance_mismatch", None, None, running, stored
                )
            )
        frozen = frozen_by_account.get(account_id, 0)
        accounts.append(
            {
                "accountId": account_id,
                "storedBalance": stored,
                "replayedBalance": running,
                "frozen": frozen,
                "availableBalance": max(0, stored - frozen),
            }
        )

    # 反向构造预期分录：在同一冻结事务内，从入金、正金额结算、
    # 直接退款（已退款且无仲裁记录的争议）、升级与仲裁记录推导每个
    # (kind, referenceSeq) 应有的账户侧与有符号金额。
    # 零金额 pending 结算仍不产生任何分录。
    arbitrated_dispute_ids = {
        arbitration["dispute_id"] for arbitration in arbitrations.values()
    }
    expected_entries: dict[tuple[str, int], dict[str, Any]] = {}

    def settlement_attribution(settlement: Any) -> tuple[Any, Any] | None:
        # 结算关联的 SLA 须存在且评估属于同一 SLA；断裂时返回
        # (预期SLA, 实际SLA) 供 entry_attribution 差异使用。
        evaluation = evaluations.get(settlement["evaluation_seq"])
        if (
            settlement["sla_id"] not in sla_ids
            or evaluation is None
            or evaluation["sla_id"] != settlement["sla_id"]
        ):
            return (
                settlement["sla_id"],
                None if evaluation is None else evaluation["sla_id"],
            )
        return None

    for deposit_seq in sorted(deposits):
        deposit = deposits[deposit_seq]
        amount = deposit["amount_micros"]
        expected_entries[("deposit", deposit_seq)] = {
            "sides": [
                (deposit["machine_id"], amount),
                (CLEARING_ACCOUNT_ID, -amount),
            ],
            "attribution": None,
            "attribution_seq": None,
            "reference_broken": False,
        }
    for settlement_seq in sorted(settlements):
        settlement = settlements[settlement_seq]
        amount = settlement["amount_micros"]
        if (
            amount <= 0
            or settlement["payer_id"] is None
            or settlement["payee_id"] is None
        ):
            continue
        expected_entries[("settlement", settlement_seq)] = {
            "sides": [
                (settlement["payer_id"], -amount),
                (settlement["payee_id"], amount),
            ],
            "attribution": settlement_attribution(settlement),
            "attribution_seq": settlement_seq,
            "reference_broken": False,
        }
    for dispute_id in sorted(disputes_by_id):
        dispute = disputes_by_id[dispute_id]
        if (
            dispute["state"] != "refunded"
            or dispute_id in arbitrated_dispute_ids
        ):
            continue
        amount = dispute["amount_micros"]
        settlement = settlements.get(dispute["settlement_seq"])
        expected_entries[("dispute_refund", dispute["settlement_seq"])] = {
            "sides": [
                (dispute["payee_id"], -amount),
                (dispute["payer_id"], amount),
            ],
            "attribution": (
                None
                if settlement is None
                else settlement_attribution(settlement)
            ),
            "attribution_seq": dispute["settlement_seq"],
            # 结算记录缺失（篡改）时沿用逐笔 entry_reference 核对。
            "reference_broken": settlement is None,
        }
    for escalation_seq in sorted(escalations):
        escalation = escalations[escalation_seq]
        dispute = disputes_by_id.get(escalation["dispute_id"])
        sides = [(CLEARING_ACCOUNT_ID, escalation["amount_micros"])]
        if dispute is not None:
            sides.insert(
                0, (dispute["payee_id"], -escalation["amount_micros"])
            )
        attribution = None
        attribution_seq = None
        if dispute is not None:
            settlement = settlements.get(dispute["settlement_seq"])
            attribution_seq = dispute["settlement_seq"]
            if settlement is None:
                attribution = (None, None)
                attribution_seq = escalation_seq
            else:
                attribution = settlement_attribution(settlement)
        expected_entries[("dispute_escalation", escalation_seq)] = {
            "sides": sides,
            "attribution": attribution,
            "attribution_seq": attribution_seq,
            "reference_broken": False,
        }
    for arbitration_seq in sorted(arbitrations):
        arbitration = arbitrations[arbitration_seq]
        dispute = disputes_by_id.get(arbitration["dispute_id"])
        sides = [(CLEARING_ACCOUNT_ID, -arbitration["amount_micros"])]
        if dispute is not None:
            recipient_id = (
                dispute["payee_id"]
                if arbitration["decision"] == "release"
                else dispute["payer_id"]
            )

            sides.append((recipient_id, arbitration["amount_micros"]))
        attribution = None
        attribution_seq = None
        reference_broken = False
        if dispute is not None:
            expected_state = (
                "released"
                if arbitration["decision"] == "release"
                else "refunded"
            )
            # 争议状态与仲裁决定不一致（篡改）时沿用逐笔 entry_reference。
            reference_broken = dispute["state"] != expected_state
            settlement = settlements.get(dispute["settlement_seq"])
            attribution_seq = dispute["settlement_seq"]
            if settlement is None:
                attribution = (None, None)
                attribution_seq = arbitration_seq
            else:
                attribution = settlement_attribution(settlement)
        expected_entries[("dispute_arbitration", arbitration_seq)] = {
            "sides": sides,
            "attribution": attribution,
            "attribution_seq": attribution_seq,
            "reference_broken": reference_broken,
        }

    # 实际分录按 (kind, referenceSeq) 归集为可重复集合：预期腿同样按出现
    # 次数逐条匹配，账户标识不得覆盖同组记录。公开模型允许 SLA 生产方与
    # 消费者为同一机器，此时同一账户须保留金额相反的两条独立分录。
    entries_by_pair: dict[tuple[str, int], list[dict[str, Any]]] = {}
    for entry in entries:
        entries_by_pair.setdefault(
            (entry["kind"], entry["reference_seq"]), []
        ).append(entry)

    for pair_key in sorted(entries_by_pair.keys() | expected_entries.keys()):
        kind, reference_seq = pair_key
        pair = entries_by_pair.get(pair_key, [])
        expected = expected_entries.get(pair_key)
        if expected is None:
            # 无对应业务记录（含未知种类）的分录：业务引用无法核对，
            # 成对计数与金额守恒沿用既有差异类型。
            for entry in pair:
                differences.append(
                    self._audit_difference(
                        entry["account_id"], "entry_reference",
                        entry["entry_seq"], reference_seq,
                    )
                )
            if len(pair) != 2:
                for entry in pair:
                    differences.append(
                        self._audit_difference(
                            entry["account_id"], "entry_unpaired",
                            entry["entry_seq"], reference_seq, 2, len(pair),
                        )
                    )
                continue
            total = self._audit_pair_delta(pair)
            if total != 0:
                differences.append(
                    self._audit_difference(
                        pair[0]["account_id"], "entry_pair_amount",
                        pair[0]["entry_seq"], reference_seq, 0, total,
                    )
                )
            continue
        sides: list[tuple[str, int]] = expected["sides"]
        if expected["reference_broken"]:
            # 业务记录链断裂（结算缺失或争议状态与仲裁决定不一致）：
            # 逐笔 entry_reference 保留实际锚点；预期腿仍按账户可重复
            # 集合计数，缺少实际分录锚点的腿逐条记 entry_missing，
            # 不能因没有实际分录而漏过业务记录。
            for entry in pair:
                differences.append(
                    self._audit_difference(
                        entry["account_id"], "entry_reference",
                        entry["entry_seq"], reference_seq,
                    )
                )
            actual_accounts = [entry["account_id"] for entry in pair]
            for account, delta in sides:
                if account in actual_accounts:
                    actual_accounts.remove(account)
                else:
                    differences.append(
                        self._audit_difference(
                            account, "entry_missing", None, None,
                            delta, None,
                        )
                    )
            continue
        side_accounts = {account for account, _ in sides}
        consumed = [False] * len(pair)
        # 每条预期腿单独锚定实际分录：先按账户与有符号金额精确消费，
        # 再按账户消费（金额/方向不符记 entry_direction）。
        matched_by_leg: list[dict[str, Any] | None] = [None] * len(sides)
        for leg_index, (account, delta) in enumerate(sides):
            for index, entry in enumerate(pair):
                if (
                    not consumed[index]
                    and entry["account_id"] == account
                    and entry["delta_micros"] == delta
                ):
                    consumed[index] = True
                    matched_by_leg[leg_index] = entry
                    break
        for leg_index, (account, delta) in enumerate(sides):
            if matched_by_leg[leg_index] is not None:
                continue
            for index, entry in enumerate(pair):
                if not consumed[index] and entry["account_id"] == account:
                    consumed[index] = True
                    matched_by_leg[leg_index] = entry
                    differences.append(
                        self._audit_difference(
                            account, "entry_direction",
                            entry["entry_seq"], reference_seq,
                            delta, entry["delta_micros"],
                        )
                    )
                    break
        # 缺失腿逐条记录（同账户缺两腿即两项）：无实际分录锚点时两个
        # 序号字段均为 null，expected 保留有符号金额，actual 固定 null。
        # 少一腿时仅产生一项 entry_missing。
        for leg_index, (account, delta) in enumerate(sides):
            if matched_by_leg[leg_index] is None:
                differences.append(
                    self._audit_difference(
                        account, "entry_missing", None, None, delta, None
                    )
                )
        # 多余分录：同账户副本记 entry_unpaired，错账户记 entry_reference；
        # 差异保留实际 entrySeq，第三条同账户副本不得被任意配对后忽略。
        for index, entry in enumerate(pair):
            if consumed[index]:
                continue
            if entry["account_id"] in side_accounts:
                differences.append(
                    self._audit_difference(
                        entry["account_id"], "entry_unpaired",
                        entry["entry_seq"], reference_seq, 2, len(pair),
                    )
                )
            else:
                differences.append(
                    self._audit_difference(
                        entry["account_id"], "entry_reference",
                        entry["entry_seq"], reference_seq,
                    )
                )
        # SLA 与评估归属：逐条预期腿核对，锚点取该腿匹配到的实际分录，
        # 无对应分录时序号为 null。
        attribution = expected["attribution"]
        if attribution is not None:
            for leg_index, (account, _delta) in enumerate(sides):
                entry = matched_by_leg[leg_index]
                differences.append(
                    self._audit_difference(
                        account, "entry_attribution",
                        None if entry is None else entry["entry_seq"],
                        expected["attribution_seq"],
                        attribution[0], attribution[1],
                    )
                )
        # 金额不守恒：两条实际分录均被预期腿消费时金额和须为零。
        if len(pair) == 2 and all(consumed):
            total = self._audit_pair_delta(pair)
            if total != 0:
                differences.append(
                    self._audit_difference(
                        pair[0]["account_id"], "entry_pair_amount",
                        pair[0]["entry_seq"], reference_seq, 0, total,
                    )
                )

    disputes_document = [
        {
            "disputeId": row["id"],
            "state": row["state"],
            "amount": row["amount_micros"],
            "claimantId": row["claimant_id"],
            "payerId": row["payer_id"],
            "payeeId": row["payee_id"],
            "settlementSeq": row["settlement_seq"],
        }
        for row in (
            disputes_by_id[key] for key in sorted(disputes_by_id)
        )
    ]

    # 未仲裁 escalated 金额计为清算负债：与升级记录及争议状态交叉核对。
    escrow_liability = sum(
        dispute["amount_micros"]
        for dispute in disputes_by_id.values()
        if dispute["state"] == "escalated"
    )
    recorded_escrow = 0
    escalations_document = []
    for escalation_seq in sorted(escalations):
        escalation = escalations[escalation_seq]
        dispute = disputes_by_id.get(escalation["dispute_id"])
        if dispute is None:
            differences.append(
                self._audit_difference(
                    CLEARING_ACCOUNT_ID, "escalation_dispute_missing",
                    None, escalation_seq,
                )
            )
            continue
        if dispute["state"] == "escalated":
            recorded_escrow += escalation["amount_micros"]
            if escalation["amount_micros"] != dispute["amount_micros"]:
                differences.append(
                    self._audit_difference(
                        CLEARING_ACCOUNT_ID, "escrow_amount_mismatch",
                        None, escalation_seq,
                        dispute["amount_micros"], escalation["amount_micros"],
                    )
                )
        escalations_document.append(
            {
                "escalationSeq": escalation_seq,
                "disputeId": escalation["dispute_id"],
                "amount": escalation["amount_micros"],
                "arbitrated": escalation["dispute_id"]
                in arbitrated_dispute_ids,
            }
        )
    if escrow_liability != recorded_escrow:
        differences.append(
            self._audit_difference(
                CLEARING_ACCOUNT_ID, "escrow_record_mismatch",
                None, None, escrow_liability, recorded_escrow,
            )
        )

    # 冻结仲裁结果，并核对仲裁与升级的归属。
    arbitrations_document = []
    for arbitration_seq in sorted(arbitrations):
        arbitration = arbitrations[arbitration_seq]
        escalation = escalations.get(arbitration["escalation_seq"])
        if (
            escalation is None
            or escalation["dispute_id"] != arbitration["dispute_id"]
        ):
            differences.append(
                self._audit_difference(
                    CLEARING_ACCOUNT_ID, "arbitration_escalation_mismatch",
                    None, arbitration_seq,
                )
            )
        arbitrations_document.append(
            {
                "arbitrationSeq": arbitration_seq,
                "escalationSeq": arbitration["escalation_seq"],
                "disputeId": arbitration["dispute_id"],
                "arbitratorId": arbitration["arbitrator_id"],
                "decision": arbitration["decision"],
                "amount": arbitration["amount_micros"],
            }
        )

    # 外部清算账户持有的是系统入金的反向镜像与升级托管：
    # 余额 = 未仲裁升级托管 − 累计入金；结算与退款只在机器账户间转移。
    deposit_total = sum(
        deposit["amount_micros"] for deposit in deposits.values()
    )
    clearing_balance = stored_balances.get(CLEARING_ACCOUNT_ID, 0)
    expected_clearing = recorded_escrow - deposit_total
    if clearing_balance != expected_clearing:
        differences.append(
            self._audit_difference(
                CLEARING_ACCOUNT_ID, "clearing_balance_mismatch",
                None, None, expected_clearing, clearing_balance,
            )
        )
    clearing_document = {
        "accountId": CLEARING_ACCOUNT_ID,
        "storedBalance": clearing_balance,
        "depositTotal": deposit_total,
        "escrowLiability": recorded_escrow,
        "expectedBalance": expected_clearing,
    }

    # 差异项按账户、类型、引用序号（再按分录序号）稳定排序。
    differences.sort(
        key=lambda item: (
            item["accountId"],
            item["type"],
            item["referenceSeq"] is None,
            item["referenceSeq"] if item["referenceSeq"] is not None else 0,
            item["entrySeq"] is None,
            item["entrySeq"] if item["entrySeq"] is not None else 0,
        )
    )

    return {
        "entrySeqBound": entry_seq_bound,
        "consistent": not differences,
        "accounts": accounts,
        "disputes": disputes_document,
        "escalations": escalations_document,
        "arbitrations": arbitrations_document,
        "clearing": clearing_document,
        "differences": differences,
    }

